     */
    case currency(
        amount: String,
        currencyCode: String
    )
    /**
     * Reference to another entity (e.g. "person.alice").
     */
    case entityReference(entityId: String
    )
    /**
     * Reference to a field on another entity.
     */
    case fieldReference(
        entityId: String,
        fieldId: String
    )
    /**
     * Ordered list of values.
     */
    case list(items: [FirmFieldValue]
    )
    /**
     * ISO 8601 / RFC 3339 datetime string.
     */
    case dateTime(value: String
    )
    /**
     * File path as string.
     */
    case path(value: String
    )
    /**
     * Enum variant name.
     */
    case `enum`(value: String
    )
}

