private struct FfiConverterSequenceTypeFirmFieldValue: FfiConverterRustBuffer {
    typealias SwiftType = [FirmFieldValue]

    static func write(_ value: [FirmFieldValue], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeFirmFieldValue.write(item, into: &buf)
        }
    }

    static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [FirmFieldValue] {
        let len: Int32 = try readInt(&buf)
        var seq = [FirmFieldValue]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            try seq.append(FfiConverterTypeFirmFieldValue.read(from: &buf))
        }
        return seq
    }
}

private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}

/// Use a global variable to perform the versioning checks. Swift ensures that
/// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_firm_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_build() != 6341 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_find_entity_source() != 50497 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_generate_entity_dsl() != 20794 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_get_entity() != 59701 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_get_related() != 27655 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_get_schema() != 11073 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_get_source() != 55347 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_list_entities() != 57618 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_list_schemas() != 49751 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_load_source() != 61835 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_method_firmsession_query() != 40065 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_firm_ffi_checksum_constructor_firmsession_new() != 24998 {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

/// Make the ensure init function public so that other modules which have external type references
/// to
/// our types can call it.
public func uniffiEnsureFirmFfiInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

